p=dist/'assets/sources.json';d=json.loads(p.read_text());assert not any(x['id']=='EA01' for x in d);report=dest/'REPORT.md';d.append({'id':'EA01','title':'Evidence admission schema and circuit disposition v0.1','group':'Recent amendments','status':'SOFTWARE CHECKED / EMPIRICAL HOLD / PHYSICAL PROMOTION0','note':'27 controls; externally trusted review receipts required; twelve reviewed roles missing; no new empirical analysis.','url':'/evidence/evidence-admission/','local':'/sources/evidence-admission-v0.1/REPORT.md','sha256':hashlib.sha256(report.read_bytes()).hexdigest(),'size_bytes':report.stat().st_size,'content':report.read_text()});p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
